import{_ as a,C as n,c as s,o as i,a3 as o,G as r}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Optional products","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/quotations-orders/optional-products.md","filePath":"master/sales/sales/quotations-orders/optional-products.md","lastUpdated":1791902625000}'),l={name:"master/sales/sales/quotations-orders/optional-products.md"};function u(d,t,c,h,p,g){const e=n("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=o('<h1 id="optional-products" tabindex="-1">Optional products <a class="header-anchor" href="#optional-products" aria-label="Permalink to &quot;Optional products&quot;">​</a></h1><p>Optional products are extra items you suggest to a customer on a quotation. They sit next to the products you are already offering, but they are not part of the price yet. Use them for add-ons, upgrades or alternatives, so the customer sees what else is possible without you changing the main offer.</p><blockquote><p><strong>In simple words:</strong> Optional products are a &quot;you might also like&quot; list saved inside the quotation. They cost nothing until you move them to the order lines.</p></blockquote><p><strong>Example:</strong> Azure Interiors asks for 5 Camping Hammocks. You also want to suggest a Smart LED Desk Lamp. Put the lamp in <strong>Optional Products</strong>. The quotation total stays at the hammocks only.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><ul><li>You want to offer an add-on, such as a carry bag with a hammock.</li><li>You want to show a better or cheaper alternative.</li><li>You want the customer to decide later, without a second quotation.</li></ul><h2 id="add-an-optional-product" tabindex="-1">Add an optional product <a class="header-anchor" href="#add-an-optional-product" aria-label="Permalink to &quot;Add an optional product&quot;">​</a></h2><ol><li><p>Go to <code>Sales → Orders → Quotations</code>.</p></li><li><p>Open a quotation, or click <strong>New Quotation</strong>. If you open a saved one, click the <strong>Edit</strong> tab.</p></li><li><p>Click the <strong>Optional Products</strong> tab.</p></li><li><p>Click <strong>Add Product</strong>.</p></li><li><p>Fill in the line:</p><ul><li><strong><em>Product:</em></strong> The item you suggest. Required. Each product can be listed only once.</li><li><strong><em>Quantity:</em></strong> How many units you suggest. Required. It starts at 1.</li><li><strong><em>UOM:</em></strong> The unit of measure, meaning the unit you count in, such as Units. Required. It shows only when <strong>Unit of Measure</strong> is on in <a href="./../configuration/settings.html">Settings</a>.</li><li><strong><em>Unit Price:</em></strong> The price of one unit. Required. It is filled from the product, and you can change it.</li><li><strong><em>Discount (%):</em></strong> A percentage off the line. It shows only when <strong>Discount</strong> is on in Settings.</li></ul></li><li><p>Click <strong>Create</strong> for a new quotation, or <strong>Save changes</strong> for a saved one.</p></li></ol>',8)),r(e,{src:"/images1/sales/optional_products_tab.png",alt:"Create Quotation page with the Optional Products tab and the Add Product button"}),t[1]||(t[1]=o('<p>To remove a line, click its delete icon and confirm.</p><h2 id="move-an-optional-product-to-the-order" tabindex="-1">Move an optional product to the order <a class="header-anchor" href="#move-an-optional-product-to-the-order" aria-label="Permalink to &quot;Move an optional product to the order&quot;">​</a></h2><p>When the customer says yes to an extra item, turn it into a real order line.</p><ol><li>Open the quotation and click the <strong>Edit</strong> tab.</li><li>Go to the <strong>Optional Products</strong> tab.</li><li>On the line, click the cart icon. Its tooltip adds the product to the order lines.</li><li>Open the <strong>Order Line</strong> tab. The product is there now, with its price and taxes filled in.</li><li>Click <strong>Save changes</strong>.</li></ol><p>After the move, the icon on the optional line turns into a green tick. This means the product is already on the order. If the product is already an order line, Aureus warns you and does not add it twice.</p><p><strong>Example:</strong> Azure Interiors agrees to the lamp. You click the cart icon. The lamp appears on <strong>Order Line</strong>, and the <strong>Amount Total</strong> now includes it.</p><h2 id="when-the-tab-is-visible" tabindex="-1">When the tab is visible <a class="header-anchor" href="#when-the-tab-is-visible" aria-label="Permalink to &quot;When the tab is visible&quot;">​</a></h2><ul><li>The tab is available while the quotation is in <strong>Quotation</strong> or <strong>Quotation Sent</strong>. It is hidden once the order is confirmed or cancelled.</li><li>On the view page, the tab shows only when the quotation has optional products. There it is a read-only table.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Add optional products before you click <strong>Send By Email</strong>. The customer then sees the suggestions in the same message.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Optional products do not change <strong>Untaxed Amount</strong>, <strong>Amount Tax</strong> or <strong>Amount Total</strong>. Only the <strong>Order Line</strong> tab does.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-quotation.html">Create a quotation</a></li><li><a href="./send-and-confirm-quotation.html">Send and confirm a quotation</a></li><li><a href="./../products-prices/discounts-margins.html">Discounts and margins</a></li><li><a href="./../configuration/settings.html">Sales settings</a></li></ul>',12))])}const b=a(l,[["render",u]]);export{f as __pageData,b as default};
